// Builds a binary search tree from an array of values.
struct node* helper_build_tree(int *values, int size) {
    struct node *root = NULL;
    for (int i = 0; i < size; ++i) {
        root = insert(root, values[i]);
    }
    return root;
}

// Creates an array containing the inorder traversal of the tree.
static void helper_inorder_fill(struct node *root, int *arr, int *idx) {
    if (root == NULL) return;
    helper_inorder_fill(root->left, arr, idx);
    arr[(*idx)++] = root->key;
    helper_inorder_fill(root->right, arr, idx);
}
int* helper_tree_to_inorder_array(struct node *root, int size) {
    int *arr = (int*)malloc(sizeof(int) * size);
    int idx = 0;
    helper_inorder_fill(root, arr, &idx);
    return arr;
}

// Counts the number of nodes in the tree.
int helper_count_nodes(struct node *root) {
    if (root == NULL) return 0;
    return 1 + helper_count_nodes(root->left) + helper_count_nodes(root->right);
}

// Frees all nodes in the tree.
void helper_free_tree(struct node *root) {
    if (root == NULL) return;
    helper_free_tree(root->left);
    helper_free_tree(root->right);
    free(root);
}


